def getMinCost(cost, time):
    n = len(cost)
    INF = float('inf')
    f = [INF] * (n + 1)          # f[j]：已经“处理掉” j 个任务的最小花费（超过 n 记为 n）
    f[0] = 0
    for c, t in zip(cost, time):
        for j in range(n, -1, -1):
            if f[j] < INF:
                nj = min(n, j + t + 1)   # 付费跑这个任务的 t 时间里，免费服务器能顺带做 t 个
                if f[j] + c < f[nj]:
                    f[nj] = f[j] + c
    return f[n]
